LARGE = 1e300


@nb.njit(cache=True)
def _find_path(n, cost, start_i, y, v, pred, d, cols):
    for k in range(n):
        cols[k] = k
        pred[k] = start_i
        d[k] = cost[start_i, k] - v[k]
    lo = 0
    hi = 0
    n_ready = 0
    final_j = -1
    while final_j == -1:
        if lo == hi:
            n_ready = lo
            # find
            hi = lo + 1
            j = cols[lo]
            mind = d[j]
            for k in range(hi, n):
                j = cols[k]
                dj = d[j]
                if dj <= mind:
                    if dj < mind:
                        hi = lo
                        mind = dj
                    cols[k] = cols[hi]
                    cols[hi] = j
                    hi += 1
            for k in range(lo, hi):
                j = cols[k]
                if y[j] < 0:
                    final_j = j
        if final_j == -1:
            # scan
            while lo != hi:
                j = cols[lo]
                lo += 1
                i = y[j]
                mind = d[j]
                h = cost[i, j] - v[j] - mind
                for k in range(hi, n):
                    j = cols[k]
                    c = cost[i, j] - v[j] - h
                    if c < d[j]:
                        d[j] = c
                        pred[j] = i
                        if c == mind:
                            if y[j] < 0:
                                final_j = j
                                break
                            cols[k] = cols[hi]
                            cols[hi] = j
                            hi += 1
                if final_j != -1:
                    break
    mind = d[cols[lo]]
    for k in range(n_ready):
        j = cols[k]
        v[j] += d[j] - mind
    return final_j


