import numpy as np
import numba as nb
from lapcore2 import _global_thr, _build, _auction, _push, _pop, INF


@nb.njit(cache=True)
def _repair_duals(C, adj, cnt, x, y, v, maxpops):
    """Given full assignment x, find column potentials v making x optimal on the
    sparse graph: v[j] <= v[x_i] + C[i,j] - C[i,x_i].  Label-correcting (SPFA).
    Returns False if it doesn't converge (likely negative cycle)."""
    n = C.shape[0]
    inq = np.ones(n, np.bool_)
    q = np.empty(n, np.int64)
    for i in range(n):
        q[i] = i
    qh = 0
    qn = n
    pops = 0
    while qn > 0:
        pops += 1
        if pops > maxpops:
            return False
        i = q[qh]
        qh += 1
        if qh == n:
            qh = 0
        qn -= 1
        inq[i] = False
        Ci = C[i]
        xi = x[i]
        base = v[xi] - Ci[xi]
        for t in range(cnt[i]):
            j = adj[i, t]
            nv = base + Ci[j]
            if nv < v[j]:
                v[j] = nv
                r = y[j]
                if not inq[r]:
                    inq[r] = True
                    pos = qh + qn
                    if pos >= n:
                        pos -= n
                    q[pos] = r
                    qn += 1
    return True


@nb.njit(cache=True)
def _verify_add(C, u, v, adj, cnt, inadj, tol):
    n = C.shape[0]
    nv = 0
    for i in range(n):
        ui = u[i]
        Ci = C[i]
        for j in range(n):
            if Ci[j] - ui - v[j] < -tol:
                if not inadj[i, j]:
                    adj[i, cnt[i]] = j
                    cnt[i] += 1
                    inadj[i, j] = True
                nv += 1
    return nv


@nb.njit(cache=True)
def _sap(C, adj, cnt, inadj, x, y, u, v):
    """Sparse shortest augmenting path completing matching; u,v must be
    dual feasible on sparse graph with matched edges tight."""
    n = C.shape[0]
    dist = np.full(n, INF)
    final = np.zeros(n, np.bool_)
    pred = np.empty(n, np.int64)
    touched = np.empty(n, np.int64)
    fin_list = np.empty(n, np.int64)
    cap = n * n + n + 1
    hk = np.empty(cap)
    hv = np.empty(cap, np.int64)
    for s in range(n):
        if x[s] >= 0:
            continue
        while True:
            mn = INF
            for t in range(cnt[s]):
                j = adj[s, t]
                c = C[s, j] - v[j]
                if c < mn:
                    mn = c
            u[s] = mn
            ntouch = 0
            nfin = 0
            sz = 0
            for t in range(cnt[s]):
                j = adj[s, t]
                c = C[s, j] - mn - v[j]
                if c < dist[j]:
                    if dist[j] == INF:
                        touched[ntouch] = j
                        ntouch += 1
                    dist[j] = c
                    pred[j] = s
                    sz = _push(hk, hv, sz, c, j)
            sink = -1
            D = 0.0
            while sz > 0:
                dj = hk[0]
                j = hv[0]
                sz = _pop(hk, hv, sz)
                if final[j] or dj > dist[j]:
                    continue
                final[j] = True
                fin_list[nfin] = j
                nfin += 1
                if y[j] < 0:
                    sink = j
                    D = dj
                    break
                i = y[j]
                base = dj - u[i]
                Ci = C[i]
                for t in range(cnt[i]):
                    jj = adj[i, t]
                    if final[jj]:
                        continue
                    c = base + Ci[jj] - v[jj]
                    if c < dist[jj]:
                        if dist[jj] == INF:
                            touched[ntouch] = jj
                            ntouch += 1
                        dist[jj] = c
                        pred[jj] = i
                        sz = _push(hk, hv, sz, c, jj)
            for k in range(ntouch):
                j = touched[k]
                if not final[j]:
                    dist[j] = INF
            if sink < 0:
                for k in range(nfin):
                    j = fin_list[k]
                    dist[j] = INF
                    final[j] = False
                for j in range(n):
                    if not inadj[s, j]:
                        adj[s, cnt[s]] = j
                        cnt[s] += 1
                        inadj[s, j] = True
                continue
            u[s] += D
            for k in range(nfin):
                j = fin_list[k]
                if j != sink:
                    dd = D - dist[j]
                    v[j] -= dd
                    u[y[j]] += dd
            j = sink
            while True:
                i = pred[j]
                y[j] = i
                tmp = x[i]
                x[i] = j
                if i == s:
                    break
                j = tmp
            for k in range(nfin):
                j = fin_list[k]
                dist[j] = INF
                final[j] = False
            break


