                v[j] = C[i, j]
    x = -np.ones(n, np.int64)
    y = -np.ones(n, np.int64)
    p = -v.copy()
    ok = _auction(C, adj, cnt, p, x, y, eps0, epsf)
    u = np.empty(n)
    if ok:
        for j in range(n):
            v[j] = -p[j]
    else:
        x[:] = -1
        y[:] = -1
    use_sap = not ok
    while True:
        if not use_sap:
            if not _repair_duals(C, adj, cnt, x, y, v, 20 * n):
                use_sap = True
                # restore a dual-feasible state for SAP: v = column minima
                for j in range(n):
                    v[j] = INF
                for i in range(n):
                    for j in range(n):
                        if C[i, j] < v[j]:
                            v[j] = C[i, j]
                for i in range(n):
                    x[i] = -1
                    y[i] = -1
        if use_sap:
            # complete the matching keeping matched edges tight
            for i in range(n):
                j = x[i]
                if j >= 0:
                    u[i] = C[i, j] - v[j]
            _sap(C, adj, cnt, inadj, x, y, u, v)
        else:
            for i in range(n):
                u[i] = C[i, x[i]] - v[x[i]]
        nviol = _verify_add(C, u, v, adj, cnt, inadj, 1e-12)
        if nviol == 0:
            return x
        if use_sap:
            # unmatch rows with violations; set u to row minimum (feasible)
            for i in range(n):
                mn = INF
                Ci = C[i]
                for j in range(n):
                    c = Ci[j] - v[j]
                    if c < mn:
                        mn = c
                if mn < u[i] - 1e-12:
                    if x[i] >= 0:
                        y[x[i]] = -1
                        x[i] = -1
