def _check_final(C, x, v):
    n = C.shape[0]
    for i in range(n):
        xi = x[i]
        base = C[i, xi] - v[xi]
        for j in range(n):
            if C[i, j] - v[j] < base:
                return False
    return True


@nb.njit(cache=True)
def lap_fast(C, K, eps0, epsf, factor):
    n = C.shape[0]
    adj = np.empty((n, n), np.int32)
    cnt = np.zeros(n, np.int64)
    inadj = np.zeros((n, n), np.bool_)
    thr = _global_thr(C, K)
    _build(C, thr, adj, cnt, inadj)
    p = np.empty(n)
    for j in range(n):
        mn = INF
        for i in range(n):
            if C[i, j] < mn:
                mn = C[i, j]
        p[j] = -mn
    x = -np.ones(n, np.int64)
    y = -np.ones(n, np.int64)
    queue = np.empty(n, np.int64)
    eps = eps0
    maxit = 200 * n
    while True:
        for i in range(n):
            x[i] = -1
            y[i] = -1
            queue[i] = i
        if not _bid_loop(C, adj, cnt, p, x, y, queue, n, eps, maxit):
            return x, False
        if eps <= epsf:
            break
        eps = max(eps * factor, epsf)
    # full eps-CS check; add missing edges and re-bid
    for rnd in range(20):
        qn = 0
        for i in range(n):
            xi = x[i]
            lim = C[i, xi] + p[xi] - eps
            Ci = C[i]
            bad = False
            for j in range(n):
                if Ci[j] + p[j] < lim:
                    bad = True
                    if not inadj[i, j]:
                        adj[i, cnt[i]] = j
                        cnt[i] += 1
                        inadj[i, j] = True
            if bad:
                queue[qn] = i
                qn += 1
        if qn == 0:
            break
        for k in range(qn):
            i = queue[k]
            y[x[i]] = -1
            x[i] = -1
        if not _bid_loop(C, adj, cnt, p, x, y, queue, qn, eps, maxit):
            return x, False
    v = -p
    if not _spfa(C, x, y, v, 50 * n):
        return x, False
    return x, _check_final(C, x, v)


def lap(C, K=40, eps0=0.05, epsf=1e-9, factor=0.15):
    x, ok = lap_fast(C, K, eps0, epsf, factor)
    if not ok:
        x = lap_safe(C, K, 0.05, 1e-5)
    return x
